SELECT s.liquidity_status, s.order_book_stop_exposed, COUNT(*) AS n, SUM(p.realized_pnl>0) AS wins, SUM(p.realized_pnl<0) AS losses, ROUND(AVG((p.exit_price-p.entry_price)/p.entry_price*100),4) AS avg_gross_pct, MIN(m.entry_quality_score) AS min_eq, MAX(m.entry_quality_score) AS max_eq, GROUP_CONCAT(p.id ORDER BY p.id) AS ids FROM paper_position p JOIN trade_signal s ON s.id=p.signal_id LEFT JOIN wallet_managed_position m ON m.entry_signal_id=p.signal_id WHERE p.opened_at>='2026-10-11 00:00:00' AND p.status IN ('CLOSED','STOPPED') GROUP BY s.liquidity_status, s.order_book_stop_exposed ORDER BY s.liquidity_status, s.order_book_stop_exposed LIMIT 40